NEW_FILES = {'tests/test_bins_on_walls.py': '"""An indoor litter bin stands against a wall (0.266.0). The walker, walking cold run 9386, of deli_a03\'s bin alone at\nan aisle\'s end: "garbage cans are usually up against walls inside buildings" (the factory\'s\ndocs/findings/walk_2026-10-23_9386/, finding 8).\n\n`furnish` draws a bin as it always has and `stand_bins_on_walls`, its last step, stands each against a wall of its\nroom -- so a bin is judged where it ends, by the arrangement census\'s own reason.\n"""\nimport glob\nimport json\nimport os\n\nimport arrangement\nimport level_design\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n\n\ndef _bins_by_reason(spec):\n    """``[(name, reason)]`` for every bin furnish stood in one spec."""\n    rooms = {r["id"]: r for r in spec.get("rooms") or [] if r.get("bounds")}\n    out = []\n    for rid, ps in arrangement.standing(spec).items():\n        if rid not in rooms:\n            continue\n        for v, why in arrangement.reasons(rooms[rid], ps):\n            if arrangement.stem(v["name"], rid) == "litter_bin" and arrangement.producer(v, rooms[rid]) == "furnish":\n                out.append((v["name"], why))\n    return out\n\n\ndef _library():\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        name = os.path.basename(p)[:-len(".json")]\n        if name.startswith("lf_"):\n            continue\n        spec = json.load(open(p, encoding="utf-8"))\n        if isinstance(spec, dict) and spec.get("rooms"):\n            yield name, spec\n\n\ndef test_every_furnished_bin_in_the_library_stands_against_a_wall():\n    """Every bin furnish stood in the library\'s own specs reads `wall` to the arrangement census: its footprint within\n    `arrangement.WALL_REACH` of its room\'s edge."""\n    seen, off = 0, []\n    for name, spec in _library():\n        for bname, why in _bins_by_reason(spec):\n            seen += 1\n            if why != "wall":\n                off.append((name, bname, why))\n    assert seen, "no furnished litter bin in the library: the census found nothing to judge"\n    assert not off, (len(off), off[:10])\n\n\ndef test_the_library_is_a_fixed_point_of_the_bin_pass():\n    moved = [(name, level_design.stand_bins_on_walls(spec)) for name, spec in _library()]\n    assert not [m for m in moved if m[1] != (0, 0)], [m for m in moved if m[1] != (0, 0)][:10]\n\n\ndef test_a_furnished_room_stands_its_bins_on_its_walls_and_moves_nothing_else():\n    """furnish with the bin pass, against the same furnish with the pass set aside: every bin it keeps reads `wall`,\n    and every other volume stands exactly where it stood."""\n    import presets\n    # presets whose builds draw bins at seed 0 (measured on 0.266.0: corner_deli 9, bank 2)\n    keys = [k for k in ("corner_deli", "bank") if k in presets.REGISTRY]\n    assert keys == ["corner_deli", "bank"], sorted(presets.REGISTRY)[:20]\n    for key in keys:\n        with_pass = presets.make(key, name="bins_%s" % key, seed=0)\n        with_pass = with_pass if isinstance(with_pass, dict) else with_pass.to_dict()\n        real = level_design.stand_bins_on_walls\n        level_design.stand_bins_on_walls = lambda spec, routes_of=None: (0, 0)\n        try:\n            without = presets.make(key, name="bins_%s" % key, seed=0)\n            without = without if isinstance(without, dict) else without.to_dict()\n        finally:\n            level_design.stand_bins_on_walls = real\n        bins = _bins_by_reason(with_pass)\n        assert bins and all(why == "wall" for _n, why in bins), (key, bins)\n        rest = lambda s: sorted((v["name"], v.get("x"), v.get("y"), v.get("z")) for v in s["volumes"]\n                                if not v["name"].startswith("litter_bin_"))\n        assert rest(with_pass) == rest(without), key\n\n\ndef test_a_bin_with_no_clear_wall_goes():\n    """A room whose walls are all taken keeps no bin in the middle of its floor."""\n    spec = {"footprint_x": 6.0, "footprint_y": 6.0, "story_height": 3.0, "wall_thick": 0.3,\n            "rooms": [{"id": "box", "story": 0, "bounds": [-3.0, -3.0, 3.0, 3.0]}],\n            "volumes": [], "partitions": []}\n    tag = level_design._room_tag(spec["rooms"][0])\n    spec["volumes"].append({"name": "litter_bin_%s_1" % tag, "x": 0.0, "y": 0.0, "z": 0.5,\n                            "size_x": 0.6, "size_y": 0.6, "size_z": 1.0})\n    # a ring of tall pieces 0.9 m from nothing: every wall spot is within 0.9 m of one\n    for i in range(-3, 4):\n        for x, y in ((i * 0.9, -2.5), (i * 0.9, 2.5), (-2.5, i * 0.9), (2.5, i * 0.9)):\n            spec["volumes"].append({"name": "post_%d_%d" % (round(x * 10), round(y * 10)), "x": x, "y": y,\n                                    "z": 0.5, "size_x": 0.3, "size_y": 0.3, "size_z": 1.0})\n    room = spec["rooms"][0]\n    spots = level_design._bin_wall_spots(spec, room, 0.6, 0.6)\n    assert spots, "the test room has no wall spot at all, so it would not test the posts"\n    moved, removed = level_design.stand_bins_on_walls(spec)\n    assert (moved, removed) == (0, 1)\n    assert not [v for v in spec["volumes"] if v["name"].startswith("litter_bin_")]\n', 'migrations/migrate_bins_on_walls.py': '#!/usr/bin/env python3\n"""\nmigrate_bins_on_walls.py  --  the library\'s litter bins stand against a wall (0.266.0)\n=====================================================================================\nOne-shot, idempotent migration over specs/*.json, lf_ specs excepted. The walker, walking cold run 9386: "garbage\ncans are usually up against walls inside buildings". `level_design.stand_bins_on_walls` -- the last step of\n`furnish` since 0.266.0 -- over every stored spec: each bin furnish stood goes to the nearest spot flush against a\nwall of its room, or goes when none is clear. Nothing else in any spec moves, so no refurnish follows.\n\n    python migrations/migrate_bins_on_walls.py            # write specs/\n    python migrations/migrate_bins_on_walls.py --check    # report only\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\n\nimport level_design  # noqa: E402\n\n\ndef main():\n    check = "--check" in sys.argv\n    specs = moved = removed = 0\n    for p in sorted(glob.glob(os.path.join(ROOT, "specs", "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not isinstance(d, dict) or not d.get("rooms"):\n            continue\n        m, r = level_design.stand_bins_on_walls(d)\n        if m or r:\n            specs += 1\n            moved += m\n            removed += r\n            if not check:\n                io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("[bins_on_walls] %d specs: %d bins moved to a wall, %d with no clear wall removed%s"\n          % (specs, moved, removed, " -- check only, nothing written" if check else ""))\n\n\nif __name__ == "__main__":\n    main()\n'}
CHANGELOG = '## [0.266.0] - an indoor litter bin stands against a wall\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 8), of deli_a03\'s\nbin alone at an aisle\'s end: "garbage cans are usually up against walls inside buildings". Of the library\'s 288 bins\nfurnish stood, none stood against a wall: 260 loose by the arrangement census, 18 aligned, 10 centred. Five recipes\ndrew the bin as a floor cluster, and the corridor\'s and hallway\'s wall runs named it while its own `where` --\n`cluster` -- sent it to the floor grid anyway: a piece is placed by its `where`, not by the list that names it.\n\n### Changed\n- **`furnish` ends by standing every bin against a wall** (`stand_bins_on_walls`, after the fixtures): each bin it\n  or an earlier release stood goes to the nearest spot flush against a wall of its room -- every 0.2 m along each\n  edge a built wall holds its whole run on, at the wall slots\' own offset, clear of exterior openings\n  (`_bin_wall_spots`) -- where `_seed_clear` lets it stand, asked with the bin set aside and backed on its wall\'s\n  edge, and off any route its room reserves (`reserves_routes`; furnish hands over the routes it already asked, so\n  none is searched twice); ties by position, so a re-run makes the same move. A bin no wall spot clears goes: a bin mid-floor is the\n  defect and a room without one is not. Its size, height and turn are kept, and NOTHING ELSE MOVES -- every recipe and\n  every draw is as it was.\n\n### Refuted and kept\n- **The bin as a wall piece in five recipes\' wall runs.** Built and measured in full before this: 241 rooms\n  re-drawn for 288 bins, because a longer wall run re-shuffles every room that has one. The suite then named what\n  the bins had nothing to do with -- bank_job\'s queued lobby lost its payphone, ATM and sofa; deli_a03 lost its ATM;\n  a store poster stood on the deli\'s open edge; a chair stood in a stair core\'s egress; foundry_heist_vertical\'s\n  stair_0 stopped traversing -- and the galleries, chapels and courtrooms the `hall` recipe furnishes took the freed\n  turns as dining tables, 267 -> 324 pieces. Kept in the factory\'s `patches/dc_bins_on_walls/draft1/`.\n\n### Library\n- `migrations/migrate_bins_on_walls.py`: the same function over the stored specs. 92 specs: 280 bins moved to a\n  wall, 8 with no clear wall removed (the corner delis\' customer floors -- deli_a01 2, deli_a02, cr_deli and\n  night_deli 1 each -- office_stepped\'s lobby 2, pawn_shop_a01\'s shop floor 1); a second run moves none. Every changed spec differs from 0.265.0 in its\n  litter bins and nothing else.\n- Census, 0.265.0 against this: the library\'s furnished bins 288 -> 280, against a wall 0 -> 280; every generated\n  standing piece loose 14.1 -> 10.8 %, rooms holding two or more loose 292 -> 238. Route census, both\n  libraries in one session: detours over 10 % 23 -> 23, closed 0 -> 0 to a body and 5 -> 5 to the bake, narrowed\n  to single file 141 -> 130 (the dressing\'s own 25 -> 16): a bin off the floor is a passage back.\n\n### Tests\n- `tests/test_bins_on_walls.py` (new): every furnished bin in the library reads `wall` to the arrangement census;\n  the library is a fixed point of the bin pass; a furnished corner deli and bank stand their bins on their walls and\n  every other volume exactly where furnish without the pass stands it; a bin no wall clears goes. All four fail on\n  0.265.0, the first on behaviour (288 bins off the wall).\n\n### Measured, the clone\n- `build.py --all` and `nav_gate.py --all` exit 0, 157 shells passed; the suite 1,821 tests, 0 failed, 31 skipped\n  (the factory\'s `patches/dc_bins_on_walls/`).\n- Drafts of this one refuted on the way, each by the suite: the bin pass\'s first stay test counted a corner bin\n  moved onto its own spot (two edges offer it); its second stood bins on rooms\' reserved routes\n  (`test_marker_room_routes`, `test_reserved_routes`) and then searched market_aisles\' routes twice.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.265.0', 'Deli Counter 0.266.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
